'use strict';
const APP_RELEASE='47';
// Restore the native iPhone route used in v24-v28. Launch directly on a tap.
const isIOS=()=>/iPhone|iPad|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
// This opens the saved conversation; clipboard handoff still requires paste/send.
const WARDROBE_PROJECT_URL_KEY='wardrobe.chatgpt.project.url';
const DEFAULT_WARDROBE_PROJECT_URL='https://chatgpt.com/g/g-p-6acbb1bcf06c8191bf8785a4c90e38b8-wardrobe-app/c/6ae08427-9110-83ea-93b6-2aa2af0442a6';
function validatedWardrobeProjectUrl(value){
 try{
  const u=new URL(String(value||'').trim());
  const project=/^\/g\/g-p-[a-z0-9-]+(?:\/project|\/c\/[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})?\/?$/i;
  const legacy=/^\/project\/[a-z0-9-]+\/?$/i;
  if(u.protocol!=='https:'||u.hostname!=='chatgpt.com'||u.port||u.username||u.password||(!project.test(u.pathname)&&!legacy.test(u.pathname)))return '';
  return u.origin+u.pathname;
 }catch{return ''}
}
function savedWardrobeProjectUrl(){
 try{const saved=localStorage.getItem(WARDROBE_PROJECT_URL_KEY);return saved===null?DEFAULT_WARDROBE_PROJECT_URL:validatedWardrobeProjectUrl(saved)}catch{return DEFAULT_WARDROBE_PROJECT_URL}
}
function chatGPTRoute(){const url=savedWardrobeProjectUrl();return url?url.replace(/\/c\/[^/]+\/?$/,'/project').replace(/(\/g\/g-p-[^/]+)\/?$/,'$1/project'):(isIOS()?'com.openai.chat://':'https://chatgpt.com/');}
function chatGPTLinks(){
 return isIOS()?'<a class="btn" href="com.openai.chat://">Open ChatGPT app</a><a class="link" href="https://chatgpt.com/" target="_blank" rel="noopener">Use website</a>':'<a class="btn" href="https://chatgpt.com/" target="_blank" rel="noopener">Open ChatGPT</a>';
}
const activeItems=()=>items.filter(it=>!it.archived&&!it.mergedInto);
const dayISO=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const validDate=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s;
const isPastTrip=t=>!!(validDate(t.endDate)&&t.endDate<dayISO());
const safeLink=s=>{try{const u=new URL(s);return /^https?:$/.test(u.protocol)?u.href:''}catch{return ''}};
const catalogSnapshot=()=>({wardrobe:profile.cloudId||dbName,items:activeItems().map(it=>({id:it.id,category:it.category,name:it.name,color:it.color,brand:it.brand,material:it.material,size:it.size,notes:it.notes,extra:it.extra,reversible:!!it.reversible,updatedAt:it.updatedAt,photoCount:(it.photos||[]).length})).sort((a,b)=>a.id.localeCompare(b.id))});
const snapshotId=()=>cyrb(JSON.stringify(catalogSnapshot()));
const parseReply=txt=>{const a=txt.indexOf('{'),b=txt.lastIndexOf('}');if(a<0||b<a)throw new Error('Paste the complete JSON reply.');return JSON.parse(txt.slice(a,b+1))};
const strictRule='The attached current catalog and labeled photographs are the ONLY wardrobe authority. Ignore remembered garments, previous conversations and older exports. Never invent IDs, substitute similar garments, or claim a purchase is already owned. If a required photo or detail is missing, say so. Owner photos and corrections override marketing references. A reversible garment is one piece, not two.';

