const oldRenderMore=renderMore;
renderMore=function(){oldRenderMore();$('#storageInfo').insertAdjacentHTML('afterend','<button class="link" data-triprecovery>Trip recovery &amp; ChatGPT settings</button>'+`<p class="muted sm" id="appVersion" style="text-align:center;margin:6px 0">Version ${APP_RELEASE}</p>`)};
renderStart=function(){const ios=/iPhone|iPad|iPod/.test(navigator.userAgent)&&!navigator.standalone;$('#banner').innerHTML=ios&&!LS.get('wardrobe-nobanner',false)?'<div class="banner"><div>Use Share → Add to Home Screen to keep your wardrobe handy.</div><button class="x" data-nobanner aria-label="Dismiss">✕</button></div>':'';$('#start').innerHTML=items.length?'':`<div class="panel"><p>Start in Closet to add categories, clothes and photos.</p><button data-go="closet">Open Closet</button></div>`};
renderHome=function(){ $('#brandName').textContent=`${profile.name}'s wardrobe`;const ts=allTrips().filter(t=>!isPastTrip(t));$('#hn-trips').textContent=ts.length?`${ts.length} journey${ts.length===1?'':'s'}`:'';const t=ts.sort((a,b)=>(a.startDate||'9999').localeCompare(b.startDate||'9999'))[0];$('#nextTrip').innerHTML=t?`<button class="nexttrip" data-hometrip="${esc(t.id)}"><span class="k">Next journey</span><span class="v">${esc(t.name)}</span><span class="s">${esc(t.where||'')}</span></button>`:'';renderStart() };
