 const archive=await zipFiles([new File([prompt],'Lookbook-instructions.txt',{type:'text/plain'}),new File([JSON.stringify(plan,null,2)],'Saved-plan.json',{type:'application/json'}),new File([JSON.stringify(manifest,null,2)],'Reference-manifest.json',{type:'application/json'}),...files]);fresh();
