 const response=await fetch(url,{headers:{Authorization:'Bearer '+access.token},signal:AbortSignal.timeout(30000),cache:'no-store'});
 if(!response.ok)throw new Error('Private handoff check failed (HTTP '+response.status+'). Tap Generate to prepare a fresh request.');
 const bundle=await response.json();if(bundle.catalogMatches!==true)throw new Error('The saved photographs and live wardrobe differ. Sync the current wardrobe, then tap Generate again.');
