const productCards=gs=>`<h3>Destination-inspired additions</h3><div class="gaps">${(gs||[]).map((g,i)=>{g=cleanProduct(g,i);return `<div class="panel"><p class="muted sm">Suggested purchase · ${esc(g.id)}</p>${g.imageUrl?`<img loading="lazy" referrerpolicy="no-referrer" src="${esc(g.imageUrl)}" alt="${esc(g.item)}" style="width:100%;max-height:220px;object-fit:contain">`:''}<h4>${esc(g.item)}</h4><p>${esc([g.brand,g.color,g.price&&g.currency+' '+g.price].filter(Boolean).join(' · '))}</p><p>${esc(g.why)}</p>${g.sizes?`<p class="muted sm">Available sizes: ${esc(g.sizes)}</p>`:''}${g.pairWith.length?`<p class="muted sm">Pair with ${g.pairWith.map(esc).join(', ')}</p>`:''}${g.checkedAt?`<p class="muted sm">Checked ${esc(g.checkedAt)}</p>`:''}${g.url?`<a href="${esc(g.url)}" target="_blank" rel="noopener noreferrer">View this product</a>`:'<p class="muted sm">No verified product link supplied</p>'}</div>`}).join('')||'<p class="muted sm">No purchase suggestions for this trip.</p>'}</div>`;
